 @GraphicsMode(GraphicsMode.Mode.NATIVE) @Test public void clockMovesWindowsWithoutStateChanges()throws Exception{final long[] n={100000};SlotsView v=new SlotsView(RuntimeEnvironment.getApplication()){@Override long nowMillis(){return n[0];}};v.layout(0,0,640,1040);v.restore("500;0;1;100000;0;1;0");Method m=SlotsView.class.getDeclaredMethod("drawVegasAmbient",Canvas.class,float.class,float.class,long.class,boolean.class);m.setAccessible(true);Bitmap a=Bitmap.createBitmap(640,1040,Bitmap.Config.ARGB_8888),b=a.copy(Bitmap.Config.ARGB_8888,true);String saved=v.serialize();m.invoke(v,new Canvas(a),640f,1040f,n[0],true);n[0]+=1400;m.invoke(v,new Canvas(b),640f,1040f,n[0],true);assertFalse(a.sameAs(b));assertEquals(saved,v.serialize());Field bw=SlotsView.class.getDeclaredField("bigWinUntil");bw.setAccessible(true);bw.setLong(v,n[0]+10000);Field st=SlotsView.class.getDeclaredField("bigWinStartAt");st.setAccessible(true);st.setLong(v,n[0]-500);Field am=SlotsView.class.getDeclaredField("bigWinAmount");am.setAccessible(true);am.setLong(v,5000);v.draw(new Canvas(b));try(java.io.FileOutputStream f=new java.io.FileOutputStream("/tmp/renders/neonvegasslots-vegasambient.png")){b.compress(Bitmap.CompressFormat.PNG,100,f);}}
